onSeeking() {
  this.#throttledTriggerTranslations.cancel(); // 暂停预翻译，防止产生大量断续的无效预翻译网络请求
  // 强制高亮展示对应处的字幕，且不在此触发翻译
  this.#syncToCurrentTime({ forceRender: true, triggerTranslations: false });
}

/**
