  const { preTrans = 90 } = this.#setting;
  const endTimeMs = currentTimeMs + preTrans * 1000;
  const subs = this.#formattedSubtitles;

  // 使用二分法定位到当前播放时间对应的起始字幕索引，避免在长字幕列表中进行全量 for 检索
